<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Download, Search } from '@element-plus/icons-vue'
import { api, items, query, download, errorText, type Page } from '../api'
import { useAuth } from '../stores/auth'
import { useLoad, monthRange, timeText, statusNames } from '../composables'
import { ElMessage } from 'element-plus'
import StatusTag from '../components/StatusTag.vue'
const auth=useAuth(),range=ref<[string,string]>(monthRange()),departmentId=ref<number|undefined>(),employeeId=ref<number|undefined>(),status=ref(''),page=ref(1),size=ref(20),total=ref(0),rows=ref<any[]>([]),departments=ref<any[]>([]),employees=ref<any[]>([]),exporting=ref(false)
function params(){return{from:range.value[0],to:range.value[1],departmentId:departmentId.value,employeeId:employeeId.value,status:status.value}}
const {loading,error,load}=useLoad(async()=>{const data=await api<Page<any>>('/attendance?'+query({...params(),page:page.value-1,size:size.value}));rows.value=items(data);total.value=data.total??rows.value.length})
onMounted(async()=>{if(auth.isAdmin)try{const [d,e]=await Promise.all([api('/departments?size=200'),api('/employees?size=200')]);departments.value=items(d);employees.value=items(e)}catch(e){ElMessage.error(errorText(e))}})
function search(){page.value=1;load()}
async function exportFile(){exporting.value=true;try{await download('/attendance/export?'+query(params()),`考勤报表_${range.value[0]}_${range.value[1]}.xlsx`)}catch(e){ElMessage.error(errorText(e))}finally{exporting.value=false}}
</script>
<template><div class="page-head"><div><div class="eyebrow">ATTENDANCE RECORDS</div><h1>{{auth.isAdmin?'考勤记录':'我的考勤'}}</h1><p>追溯出勤与人工修正，所有统计使用同一筛选范围。</p></div><el-button type="primary" :icon="Download" :loading="exporting" @click="exportFile">导出报表</el-button></div><div class="panel"><div class="toolbar"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" :clearable="false" range-separator="—" start-placeholder="开始日期" end-placeholder="结束日期" style="width:255px"/><el-select v-if="auth.isAdmin" v-model="departmentId" placeholder="全部部门" clearable style="width:145px"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-select v-if="auth.isAdmin" v-model="employeeId" placeholder="全部员工" filterable clearable style="width:150px"><el-option v-for="e in employees" :key="e.id" :label="`${e.name} · ${e.employeeNo}`" :value="e.id"/></el-select><el-select v-model="status" placeholder="全部状态" clearable style="width:130px"><el-option v-for="s in ['PENDING','NORMAL','ABSENT','MISSING_IN','MISSING_OUT','LEAVE','REST']" :key="s" :label="statusNames[s]" :value="s"/><el-option label="迟到" value="LATE"/><el-option label="早退" value="EARLY"/></el-select><el-button :icon="Search" type="primary" @click="search">查询</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" empty-text="当前筛选范围暂无考勤记录"><el-table-column label="员工" min-width="145"><template #default="{row}"><div class="name-cell"><span class="avatar">{{row.employeeName?.slice(0,1)}}</span><div>{{row.employeeName}}<small>{{row.employeeNo}}</small></div></div></template></el-table-column><el-table-column prop="departmentName" label="部门" min-width="120"/><el-table-column prop="date" label="日期" width="120"/><el-table-column label="签到时间" width="110"><template #default="{row}">{{timeText(row.checkIn)}}</template></el-table-column><el-table-column label="签退时间" width="110"><template #default="{row}">{{timeText(row.checkOut)}}</template></el-table-column><el-table-column label="考勤状态" min-width="180"><template #default="{row}"><StatusTag :status="row.status" :late="row.late" :early="row.early"/></template></el-table-column><el-table-column label="人工修正" width="100"><template #default="{row}">{{row.correctionCount||0}} 次</template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[20,50,100]" layout="total, prev, pager, next, sizes" @change="load"/></div></div><p class="footnote">导出包含考勤明细及月度汇总两个工作表。签到取当天首次有效记录，签退取当天最后一次有效记录。</p></template>
